import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:hermes_app/src/chat/todo_plan/todo_plan_state.dart';

void main() {
  final fixture = jsonDecode(
    File('test/fixtures/gateway/todo_state.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  test(
    'todo text and statuses match a fixture generated by the pinned TodoStore',
    () {
      expect(fixture['source_ref'], '167e9fdb84248cd0fff80762dc57b6a914b6e930');
      final snapshot = TodoSnapshot.decode(fixture['state'])!;
      expect(snapshot.entries.map((item) => item!.content), [
        'Review the change',
        'Implement the change',
        'Verify the change',
        'Discard obsolete work',
      ]);
      expect(snapshot.entries.map((item) => item!.status), [
        TodoStatus.pending,
        TodoStatus.inProgress,
        TodoStatus.completed,
        TodoStatus.cancelled,
      ]);
      expect(snapshot.entries[1]!.parent, 'plan');
    },
  );

  test(
    'todo snapshots replace tasks and ignore repeated or older revisions',
    () {
      final owner = TodoScope(
        connection: Object(),
        runtimeId: 'runtime',
        profile: 'work',
      );
      final state = TodoPlanState()..adopt(owner);
      addTearDown(state.dispose);
      state.updated(owner, {
        'revision': 6,
        'todos': [
          {'id': 'a', 'content': 'Current task', 'status': 'pending'},
        ],
      });
      state.updated(owner, {
        'revision': 5,
        'todos': [
          {'id': 'b', 'content': 'Old task', 'status': 'completed'},
        ],
      });
      state.updated(owner, {'revision': 6, 'todos': []});
      expect(state.snapshot!.entries.single!.content, 'Current task');
      state.updated(owner, {'revision': 7, 'todos': []});
      expect(state.snapshot!.entries, isEmpty);
    },
  );

  test('unsupported entries keep supported siblings readable without invented counts', () {
    final snapshot = TodoSnapshot.decode({
      'revision': 1,
      'todos': [
        {'id': 'a', 'content': 'Known task', 'status': 'completed'},
        {'title': 'Unverified field', 'done': true},
        {'id': 'b', 'content': 'Future task', 'status': 'future'},
      ],
    })!;
    expect(snapshot.entries.first!.content, 'Known task');
    expect(snapshot.unsupportedCount, 2);
    expect(snapshot.completedCount, isNull);
  });

  test('resume adoption resets revision comparison and missing state is unavailable', () {
    final oldOwner = TodoScope(
      connection: Object(),
      runtimeId: 'runtime',
      profile: 'work',
    );
    final newOwner = TodoScope(
      connection: Object(),
      runtimeId: 'runtime',
      profile: 'work',
    );
    final state = TodoPlanState()..adopt(oldOwner);
    addTearDown(state.dispose);
    state.updated(oldOwner, {
      'revision': 6,
      'todos': [
        {'id': 'a', 'content': 'Old', 'status': 'pending'},
      ],
    });
    state.adopt(newOwner);
    state.resumed(newOwner, {'todo_state': fixture['state']});
    expect(state.snapshot!.revision, 1);
    state.updated(oldOwner, {'revision': 7, 'todos': []});
    expect(state.snapshot!.entries, hasLength(4));
    final missingOwner = TodoScope(
      connection: Object(),
      runtimeId: 'runtime',
      profile: 'work',
    );
    state.adopt(missingOwner);
    state.resumed(missingOwner, {});
    expect(state.snapshot, isNull);
    expect(state.unavailable, isTrue);
  });

  test('reconnecting within one runtime generation ignores an older resume snapshot', () {
    final connection = Object();
    final owner = TodoScope(
      connection: connection,
      runtimeId: 'runtime',
      profile: 'work',
    );
    final reconnect = TodoScope(
      connection: connection,
      runtimeId: 'runtime',
      profile: 'work',
    );
    final state = TodoPlanState()..adopt(owner);
    addTearDown(state.dispose);
    state.updated(owner, {
      'revision': 6,
      'todos': [
        {'id': 'a', 'content': 'Current task', 'status': 'pending'},
      ],
    });
    state.adopt(reconnect);
    state.resumed(reconnect, {
      'todo_state': {'revision': 5, 'todos': []},
    });
    expect(state.snapshot!.revision, 6);
    expect(state.snapshot!.entries.single!.content, 'Current task');
  });

  test('a missing same-binding resume preserves a newer live plan', () {
    final owner = TodoScope(
      connection: Object(),
      runtimeId: 'runtime',
      profile: 'work',
    );
    final state = TodoPlanState()..adopt(owner);
    addTearDown(state.dispose);
    state.updated(owner, {
      'revision': 6,
      'todos': [
        {'id': 'a', 'content': 'Current task', 'status': 'pending'},
      ],
    });

    state.resumed(owner, {});

    expect(state.snapshot!.revision, 6);
    expect(state.snapshot!.entries.single!.content, 'Current task');
  });

  test(
    'todo outcome logs contain only fixed metadata and cannot break updates',
    () {
      final seen = <Map<String, Object>>[];
      final owner = TodoScope(
        connection: Object(),
        runtimeId: 'private-id',
        profile: 'private-profile',
      );
      final state = TodoPlanState(
        events: (name, [attributes = const {}]) {
          seen.add(Map.from(attributes));
          throw StateError('Telemetry unavailable');
        },
      )..adopt(owner);
      addTearDown(state.dispose);
      expect(
        state.updated(owner, {
          'revision': 1,
          'todos': [
            {
              'id': 'private-task',
              'content': 'Private task text',
              'status': 'pending',
            },
          ],
        }),
        isTrue,
      );
      expect(seen, [
        {'feature': 'todo_state', 'outcome': 'applied', 'count': 1},
      ]);
    },
  );
}
